/* ===================== BÀI 49 · Tick và scheduler hợp tác ===================== */
/* Bài 49 · Tick và scheduler hợp tác (AMTS-EMB-001-M13-L01, MC51-049) — sinh bởi tools/author/mcu8051/l49.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P49=[{"label":"Ví dụ: Tick 250 µs bằng Timer 0 chế độ 2","code":"; Ví dụ 1: tick 250 µs bằng Timer 0 chế độ 2 (tự nạp lại)\n; AT89S52, 12 MHz: 1 chu kỳ máy (CK) = 1 µs\nTICK    DATA    30H                     ; số tick, chỉ ISR được tăng\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH                   ; vectơ ngắt Timer 0\n        INC     TICK                    ; ISR ngắn: 1 lệnh + RETI\n        RETI\n        ORG     0030H\nMAIN:   MOV     TMOD,#02H               ; Timer 0 chế độ 2: 8 bit tự nạp\n        MOV     TH0,#06H                ; 256 - 250 = 6: tràn sau 250 CK\n        MOV     TL0,#06H\n        SETB    ET0                     ; cho phép ngắt Timer 0\n        SETB    EA\n        SETB    TR0                     ; bắt đầu đếm\nCHO:    MOV     A,TICK\n        CJNE    A,#8,CHO                ; chờ đủ 8 tick = 2 ms\n        CLR     TR0                     ; dừng tick để kết thúc ví dụ\n        CLR     EA\n        SJMP    $\n        END\n","note":"Bấm Từng bước tới vòng CHO rồi đổi sang Chạy: TICK tăng 1 mỗi 250 µs. Dừng giữa chừng và xem phần Thời gian: TF0 bật mỗi 250 CK, ngay sau đó là một đoạn “đang phục vụ ngắt” ngắn. Đoán trước: sau khi chạy xong TICK bằng bao nhiêu? (08H.)","dev":{"led":true},"fosc":12000000,"speed":"real","watch":{"title":"Biến theo dõi","vars":[["TICK 30H",48,"dec"]],"hint":"TICK tăng 1 sau mỗi 250 chu kỳ máy (250 µs). Chọn tốc độ Thời gian thực để xem tick chạy; Từng bước để thấy chương trình nhảy vào 000BH."}},{"label":"Ví dụ: Scheduler hợp tác với hai tác vụ","code":"; Ví dụ 2: scheduler hợp tác, hai tác vụ theo tick\n; A: đổi LED P1.0 mỗi 4 tick · B: đổi LED P1.1 mỗi 6 tick\nTICK    DATA    30H                     ; ISR tăng\nLAST    DATA    31H                     ; tick main đã xử lý xong\nCNTA    DATA    32H                     ; đếm ngược tới lần chạy A\nCNTB    DATA    33H                     ; đếm ngược tới lần chạy B\nRUNA    DATA    34H                     ; số lần A đã chạy\nRUNB    DATA    35H                     ; số lần B đã chạy\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     TICK\n        RETI\n        ORG     0030H\nMAIN:   MOV     CNTA,#4\n        MOV     CNTB,#6\n        MOV     TMOD,#02H               ; tick 250 µs như ví dụ 1\n        MOV     TH0,#06H\n        MOV     TL0,#06H\n        SETB    ET0\n        SETB    EA\n        SETB    TR0\nVONG:   MOV     A,TICK                  ; có tick mới chưa?\n        CJNE    A,LAST,MOI\n        SJMP    VONG\nMOI:    INC     LAST                    ; xử lý đúng một tick\n        DJNZ    CNTA,XB                 ; tới lượt A chưa?\n        MOV     CNTA,#4                 ; nạp lại chu kỳ của A\n        CPL     P1.0                    ; tác vụ A (ngắn, không chờ)\n        INC     RUNA\nXB:     DJNZ    CNTB,XONG\n        MOV     CNTB,#6\n        CPL     P1.1                    ; tác vụ B\n        INC     RUNB\nXONG:   MOV     A,LAST\n        CJNE    A,#20,VONG              ; chạy 20 tick (5 ms) rồi dừng\n        CLR     EA\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Theo dõi CNTA, CNTB trong bảng Biến: mỗi tick giảm 1, về 0 thì tác vụ chạy (LED đổi) và bộ đếm nạp lại 4 hoặc 6. Sau 20 tick: RUNA = 5, RUNB = 3, LED P1.0 và P1.1 cùng sáng (P1 = FCH).","dev":{"led":true},"fosc":12000000,"speed":"real","watch":{"title":"Biến của bộ lập lịch","vars":[["TICK",48,"dec"],["LAST",49,"dec"],["CNTA",50,"dec"],["CNTB",51,"dec"],["RUNA",52,"dec"],["RUNB",53,"dec"]],"hint":"Mỗi tick mới, CNTA và CNTB giảm 1; về 0 thì tác vụ chạy và đếm được nạp lại 4 hoặc 6."}},{"label":"Bẫy: So sánh tick qua mốc tràn 8 bit","code":"; Bẫy: so sánh tick với hạn chót khi tick sắp quay vòng\n; Muốn chờ 20 tick. Giả định hệ đã chạy lâu: TICK = F0H.\nTICK    DATA    30H\nSTART   DATA    31H                     ; tick lúc bắt đầu chờ\nDEAD    DATA    32H                     ; hạn chót = START + 20\nWAITED  DATA    33H                     ; số tick thật sự đã chờ\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     TICK\n        RETI\n        ORG     0030H\nMAIN:   MOV     TICK,#0F0H\n        MOV     TMOD,#02H\n        MOV     TH0,#06H\n        MOV     TL0,#06H\n        SETB    ET0\n        SETB    EA\n        SETB    TR0\n        MOV     START,TICK\n        MOV     A,START\n        ADD     A,#20                   ; F0H + 14H = 04H (tràn 8 bit!)\n        MOV     DEAD,A\nCHO:    MOV     A,TICK                  ; SAI: hết giờ khi TICK >= DEAD\n        CLR     C\n        SUBB    A,DEAD                  ; CY = 1 khi TICK < DEAD\n        JC      CHO\n        MOV     A,TICK                  ; đo số tick đã chờ\n        CLR     C\n        SUBB    A,START\n        MOV     WAITED,A                ; mong 20, thực tế 0\n        CLR     EA\n        CLR     TR0\n        SJMP    $\n        END\n","note":"DEAD = F0H + 14H = 04H vì tràn 8 bit. Lần so đầu tiên TICK = F0H không nhỏ hơn 04H nên chương trình thoát ngay: WAITED = 0 thay vì 20, chỉ sau 29 chu kỳ máy.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Biến theo dõi","vars":[["TICK",48,"hex"],["START",49,"hex"],["DEAD",50,"hex"],["WAITED",51,"dec"]],"hint":"DEAD = F0H + 14H = 04H vì phép cộng tràn 8 bit; ngay lần so đầu TICK = F0H ≥ 04H nên chương trình coi như đã hết giờ."}},{"label":"Sửa: Đo thời gian trôi bằng phép trừ","code":"; Sửa: đo thời gian trôi bằng phép trừ không dấu\n; Hết giờ khi (TICK - START) mod 256 >= 20, đúng cả khi tràn\nTICK    DATA    30H\nSTART   DATA    31H\nWAITED  DATA    33H\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     TICK\n        RETI\n        ORG     0030H\nMAIN:   MOV     TICK,#0F0H              ; cùng giả định: tick sắp quay vòng\n        MOV     TMOD,#02H\n        MOV     TH0,#06H\n        MOV     TL0,#06H\n        SETB    ET0\n        SETB    EA\n        SETB    TR0\n        MOV     START,TICK\nCHO:    MOV     A,TICK\n        CLR     C\n        SUBB    A,START                 ; A = số tick đã trôi (mod 256)\n        CJNE    A,#20,KT                ; CY = 1 khi A < 20\nKT:     JC      CHO                     ; chưa đủ 20 tick thì chờ tiếp\n        MOV     WAITED,A                ; 20 tick = 5 ms\n        CLR     EA\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Cùng giả định TICK bắt đầu ở F0H, nhưng so số tick đã trôi (TICK − START) với 20. Xem TICK đi qua FFH → 00H trong bảng Biến: hiệu vẫn tăng đều, chương trình chờ đúng 20 tick (khoảng 5 ms) và WAITED = 14H.","dev":{"led":true},"fosc":12000000,"speed":"real","watch":{"title":"Biến theo dõi","vars":[["TICK",48,"hex"],["START",49,"hex"],["WAITED",51,"dec"]],"hint":"TICK đi F0H → FFH → 00H → 04H; hiệu TICK − START vẫn tăng đều 0, 1, …, 20."}},{"label":"Bẫy: Tác vụ dài hơn chu kỳ tick","code":"; Bẫy: tác vụ dài hơn chu kỳ tick (tick 250 CK, tác vụ ~400 CK)\nTICK    DATA    30H\nLAST    DATA    31H                     ; tick đã xử lý\nLAG     DATA    32H                     ; độ trễ lớn nhất (tick chưa xử lý)\nOVR     DATA    33H                     ; số lần phát hiện bị trễ\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     TICK\n        RETI\n        ORG     0030H\nMAIN:   MOV     TMOD,#02H\n        MOV     TH0,#06H\n        MOV     TL0,#06H\n        SETB    ET0\n        SETB    EA\n        SETB    TR0\nVONG:   MOV     A,TICK\n        CLR     C\n        SUBB    A,LAST                  ; A = số tick đang chờ xử lý\n        JZ      VONG\n        CJNE    A,#2,$+3                ; CY = 1 khi A < 2\n        JC      DUNG                    ; chỉ 1 tick chờ: đúng hạn\n        INC     OVR                     ; >= 2 tick chờ: đã lỡ hạn\nDUNG:   CJNE    A,LAG,$+3               ; cập nhật độ trễ lớn nhất\n        JC      XL\n        MOV     LAG,A\nXL:     INC     LAST\n        MOV     R7,#200                 ; tác vụ \"nặng\": 1 + 200 x 2 CK\n        DJNZ    R7,$\n        MOV     A,LAST\n        CJNE    A,#10,VONG              ; xử lý 10 tick rồi dừng\n        CLR     EA\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Mỗi lần xử lý tốn khoảng 420 µs trong khi tick đến mỗi 250 µs. Xem TICK − LAST tăng dần trong bảng Biến: sau 10 lần xử lý, TICK = 18, đã lỡ hạn 8 lần (OVR = 8), có lúc nợ 7 tick (LAG = 7). ISR vẫn đếm đúng, nhưng tác vụ chạy trễ.","dev":{"led":true},"fosc":12000000,"speed":"real","watch":{"title":"Biến theo dõi","vars":[["TICK",48,"dec"],["LAST",49,"dec"],["LAG",50,"dec"],["OVR",51,"dec"]],"hint":"Mỗi lần xử lý tốn khoảng 420 µs trong khi tick đến mỗi 250 µs: TICK − LAST (số tick chờ) tăng dần."}}];
const sim49=makeSim51(document.getElementById("m51-l49"),{id:"s49",presets:P49,ram:256});
makeEx51(document.getElementById("ex-l49"),"l49",[{"t":"Hết giờ chưa?","d":"<p>Bộ đếm tick 8 bit quay vòng: ô <code>30H<\/code> = NOW (tick hiện tại), <code>31H<\/code> = START (tick lúc bắt đầu chờ), <code>32H<\/code> = DUR (số tick cần chờ). Ghi vào <code>33H<\/code> số tick đã trôi = (NOW − START) mod 256 và vào <code>34H<\/code> giá trị <code>01H<\/code> nếu đã trôi ≥ DUR (hết giờ), ngược lại <code>00H<\/code>. Kết quả phải đúng cả khi tick đã quay qua FFH → 00H. Các ô 30H–32H giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: NOW = 25H, START = 10H, DUR = 14H → <code>33H = 15H<\/code>, <code>34H = 01H<\/code>.<\/p>","start":"; Hết giờ chưa? (code mẫu: so với hạn chót, sai khi tràn)\n        ORG     0000H\n        MOV     A,30H                   ; số tick đã trôi = NOW - START\n        CLR     C\n        SUBB    A,31H\n        MOV     33H,A\n        MOV     A,31H                   ; hạn chót = START + DUR\n        ADD     A,32H\n        MOV     R2,A\n        MOV     A,30H                   ; hết giờ khi NOW >= hạn chót ?\n        CLR     C\n        SUBB    A,R2\n        MOV     34H,#00H\n        JC      XONG\n        MOV     34H,#01H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":37,"0x31":16,"0x32":20}},"expect":{"iram":{"0x30":37,"0x31":16,"0x32":20,"0x33":21,"0x34":1}}},{"setup":{"iram":{"0x30":32,"0x31":16,"0x32":20},"regs":{"PSW":128}},"expect":{"iram":{"0x30":32,"0x31":16,"0x32":20,"0x33":16,"0x34":0}}},{"setup":{"iram":{"0x30":4,"0x31":240,"0x32":20}},"expect":{"iram":{"0x30":4,"0x31":240,"0x32":20,"0x33":20,"0x34":1}}},{"setup":{"iram":{"0x30":3,"0x31":240,"0x32":20}},"expect":{"iram":{"0x30":3,"0x31":240,"0x32":20,"0x33":19,"0x34":0}}},{"setup":{"iram":{"0x30":250,"0x31":240,"0x32":20}},"expect":{"iram":{"0x30":250,"0x31":240,"0x32":20,"0x33":10,"0x34":0}}},{"setup":{"iram":{"0x30":119,"0x31":119,"0x32":0}},"expect":{"iram":{"0x30":119,"0x31":119,"0x32":0,"0x33":0,"0x34":1}}},{"setup":{"iram":{"0x30":118,"0x31":119,"0x32":255}},"expect":{"iram":{"0x30":118,"0x31":119,"0x32":255,"0x33":255,"0x34":1}}}]},"hints":["Chạy code mẫu với NOW = 04H, START = F0H, DUR = 14H: hạn chót START + DUR bằng bao nhiêu sau khi tràn 8 bit?","Đừng so NOW với hạn chót. Tính số tick đã trôi bằng SUBB (nhớ CLR C trước), rồi so số đó với DUR.","Kết quả là cờ CY (đảo lại) đổi thành 00H/01H, không cần nhánh."],"why":"Phép trừ không dấu (NOW − START) mod 256 cho đúng số tick đã trôi kể cả khi bộ đếm quay vòng, miễn là thời gian chờ ngắn hơn 256 tick. So NOW ≥ START + DUR sai ngay khi START + DUR tràn: bộ thử 3 và 5."},{"t":"Một bước bộ lập lịch","d":"<p>Bộ lập lịch có 3 tác vụ. Ô <code>40H<\/code>, <code>41H<\/code>, <code>42H<\/code> là bộ đếm ngược của tác vụ 0, 1, 2 (luôn ≥ 1 khi vào); <code>48H<\/code>, <code>49H<\/code>, <code>4AH<\/code> là chu kỳ (số tick) của từng tác vụ; bit <i>i<\/i> của <code>50H<\/code> (READY) = 1 nghĩa là tác vụ <i>i<\/i> đang chờ được chạy. Viết <b>một bước<\/b> của bộ lập lịch (chạy một lần sau mỗi tick): với từng tác vụ, giảm bộ đếm 1; nếu về 0 thì nạp lại bằng chu kỳ và bật bit <i>i<\/i> của READY. Các bit khác của READY phải giữ nguyên; ô chu kỳ không đổi. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: đếm = 01H 03H 05H, chu kỳ = 04H 06H 0AH, READY = 00H → đếm = 04H 02H 04H, READY = 01H.<\/p>","start":"; Một bước của bộ lập lịch (gọi một lần sau mỗi tick)\n; 40H..42H: đếm ngược · 48H..4AH: chu kỳ · 50H: READY\n        ORG     0000H\n; tác vụ 0 đã viết sẵn\n        DJNZ    40H,TAC1                ; giảm 1, chưa về 0 thì bỏ qua\n        MOV     40H,48H                 ; nạp lại chu kỳ\n        ORL     50H,#01H                ; báo tác vụ 0 sẵn sàng\nTAC1:                                   ; viết tiếp cho tác vụ 1 (41H, 49H, bit\n                                        ; 1)\n; và tác vụ 2 (42H, 4AH, bit 2)\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":1,"0x41":3,"0x42":5,"0x48":4,"0x49":6,"0x4A":10,"0x50":0}},"expect":{"iram":{"0x40":4,"0x41":2,"0x42":4,"0x48":4,"0x49":6,"0x4A":10,"0x50":1}}},{"setup":{"iram":{"0x40":2,"0x41":3,"0x42":4,"0x48":4,"0x49":6,"0x4A":10,"0x50":0}},"expect":{"iram":{"0x40":1,"0x41":2,"0x42":3,"0x48":4,"0x49":6,"0x4A":10,"0x50":0}}},{"setup":{"iram":{"0x40":3,"0x41":1,"0x42":2,"0x48":4,"0x49":6,"0x4A":10,"0x50":0}},"expect":{"iram":{"0x40":2,"0x41":6,"0x42":1,"0x48":4,"0x49":6,"0x4A":10,"0x50":2}}},{"setup":{"iram":{"0x40":1,"0x41":1,"0x42":1,"0x48":4,"0x49":6,"0x4A":10,"0x50":0}},"expect":{"iram":{"0x40":4,"0x41":6,"0x42":10,"0x48":4,"0x49":6,"0x4A":10,"0x50":7}}},{"setup":{"iram":{"0x40":2,"0x41":5,"0x42":1,"0x48":2,"0x49":6,"0x4A":1,"0x50":128}},"expect":{"iram":{"0x40":1,"0x41":4,"0x42":1,"0x48":2,"0x49":6,"0x4A":1,"0x50":132}}},{"setup":{"iram":{"0x40":1,"0x41":2,"0x42":1,"0x48":9,"0x49":6,"0x4A":3,"0x50":2}},"expect":{"iram":{"0x40":9,"0x41":1,"0x42":3,"0x48":9,"0x49":6,"0x4A":3,"0x50":7}}}]},"hints":["Tác vụ 0 đã viết sẵn bằng DJNZ trên ô nhớ trực tiếp. Có thể chép thành ba đoạn, đổi địa chỉ và bit.","Bật bit mà giữ các bit khác: dùng ORL 50H,#… chứ không MOV 50H,… (bộ thử 5 và 6 có sẵn bit khác trong READY).","Muốn gọn hơn: dùng R0 trỏ bộ đếm, R1 trỏ chu kỳ, R2 là mặt nạ bit (01H, 02H, 04H) và lặp 3 lần với RL A để dịch mặt nạ."],"why":"Mỗi tác vụ có bộ đếm riêng nên các tác vụ với chu kỳ khác nhau chạy độc lập trên cùng một tick. READY là “hộp thư” giữa bộ lập lịch và vòng lặp chính: chỉ được bật thêm bit (ORL), không ghi đè, vì vòng lặp chính có thể chưa kịp chạy tác vụ đã sẵn sàng từ tick trước."},{"t":"Timeout 16 bit dưới 20 chu kỳ","d":"<p>Tick 16 bit (byte thấp trước): NOW ở <code>30H<\/code>/<code>31H<\/code>, START ở <code>32H<\/code>/<code>33H<\/code>, DUR ở <code>34H<\/code>/<code>35H<\/code>. Code mẫu so NOW với hạn chót START + DUR nên sai khi bộ đếm quay qua FFFFH → 0000H. Sửa để <code>36H<\/code> = <code>01H<\/code> khi (NOW − START) mod 65536 ≥ DUR, ngược lại <code>00H<\/code>; các ô 30H–35H giữ nguyên. Chỉ tiêu (đoạn mã này chạy sau mỗi tick nên phải rẻ): toàn chương trình không quá <b>20 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và không quá <b>26 byte<\/b> mã.<\/p><p>Ví dụ: NOW = 1234H, START = 1000H, DUR = 0200H → <code>36H = 01H<\/code>.<\/p>","start":"; Timeout 16 bit (code mẫu có lỗi: NOW >= START + DUR)\n        ORG     0000H\n        MOV     A,32H                   ; hạn chót = START + DUR (16 bit)\n        ADD     A,34H\n        MOV     R2,A\n        MOV     A,33H\n        ADDC    A,35H\n        MOV     R3,A\n        MOV     A,30H                   ; NOW - hạn chót\n        CLR     C\n        SUBB    A,R2\n        MOV     A,31H\n        SUBB    A,R3\n        JC      CHUA                    ; NOW < hạn chót: chưa hết giờ\n        MOV     36H,#01H\n        SJMP    XONG\nCHUA:   MOV     36H,#00H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":52,"0x31":18,"0x32":0,"0x33":16,"0x34":0,"0x35":2}},"expect":{"iram":{"0x30":52,"0x31":18,"0x32":0,"0x33":16,"0x34":0,"0x35":2,"0x36":1}}},{"setup":{"iram":{"0x30":52,"0x31":18,"0x32":0,"0x33":16,"0x34":0,"0x35":3}},"expect":{"iram":{"0x30":52,"0x31":18,"0x32":0,"0x33":16,"0x34":0,"0x35":3,"0x36":0}}},{"setup":{"iram":{"0x30":16,"0x31":0,"0x32":0,"0x33":255,"0x34":16,"0x35":1},"regs":{"PSW":128}},"expect":{"iram":{"0x30":16,"0x31":0,"0x32":0,"0x33":255,"0x34":16,"0x35":1,"0x36":1}}},{"setup":{"iram":{"0x30":15,"0x31":0,"0x32":0,"0x33":255,"0x34":16,"0x35":1}},"expect":{"iram":{"0x30":15,"0x31":0,"0x32":0,"0x33":255,"0x34":16,"0x35":1,"0x36":0}}},{"setup":{"iram":{"0x30":240,"0x31":255,"0x32":0,"0x33":255,"0x34":16,"0x35":1}},"expect":{"iram":{"0x30":240,"0x31":255,"0x32":0,"0x33":255,"0x34":16,"0x35":1,"0x36":0}}},{"setup":{"iram":{"0x30":0,"0x31":90,"0x32":255,"0x33":89,"0x34":1,"0x35":0}},"expect":{"iram":{"0x30":0,"0x31":90,"0x32":255,"0x33":89,"0x34":1,"0x35":0,"0x36":1}}},{"setup":{"iram":{"0x30":0,"0x31":128,"0x32":0,"0x33":128,"0x34":0,"0x35":0}},"expect":{"iram":{"0x30":0,"0x31":128,"0x32":0,"0x33":128,"0x34":0,"0x35":0,"0x36":1}}}],"maxCyc":20,"maxBytes":26},"hints":["Chạy code mẫu với bộ thử 5 (NOW = FFF0H, START = FF00H, DUR = 0110H): hạn chót tràn thành 0010H nên NOW trông như đã quá hạn.","Trừ 16 bit: byte thấp SUBB với CY = 0, byte cao SUBB dùng tiếp cờ mượn. Cất hiệu vào R2 (thấp), R3 (cao).","Không cần nhánh: phép trừ tiếp cho ra cờ CY; đổi cờ thành 00H/01H như bài tập 1."],"why":"Hai chuỗi trừ có mượn độc lập: chuỗi thứ nhất tính số tick đã trôi (đúng qua mốc tràn), chuỗi thứ hai chỉ dùng cờ mượn để so với DUR. Không dùng lệnh nhảy nên số chu kỳ không đổi theo dữ liệu (18 chu kỳ, 25 byte) — tính chất quý khi đoạn mã chạy trong mỗi tick."}]);

/* Bảng “Sơ đồ trạng thái” của Chương 13 (sinh bởi tools/author/mcu8051/m13lib.py): đọc RAM của máy giả lập, không đổi trình mô phỏng. */
(function(){const R=document.getElementById("m51-l49"),PS=P49,H2=v=>v.toString(16).toUpperCase().padStart(2,"0");let pi=-1,sec=null,last=null,prevS=null,edge=-1,seen=null;
 function rd(m,a){if(typeof a==="string"){const x=/^([0-9A-F]+)H\.([0-7])$/i.exec(a);return x?(m.iram[parseInt(x[1],16)]>>+x[2])&1:0}return a>=0x80&&a<0x100&&PS[pi].watch.sfr?m.sfr[a-0x80]:m.iram[a]}
 function shape(w){if(!sec){sec=document.createElement("section");sec.className="pn m13-w";sec.innerHTML='<div class="pane-h"><span>Sơ đồ trạng thái</span><span class="m13-h"></span></div><div class="m51-sec m13-b"></div>';}
  const sc=R.querySelector(".st-scroll");if(sec.parentNode!==sc)sc.insertBefore(sec,sc.firstChild);sec.hidden=!w;if(!w)return;
  sec.querySelector(".pane-h span").textContent=w.title||"Sơ đồ trạng thái";
  let h="";if(w.states)h+='<div class="m13-st" role="list" aria-label="Các trạng thái">'+w.states.map((s,i)=>'<span class="s" role="listitem" data-s="'+i+'">'+s+'</span>').join("")+'</div>';
  if(w.edges)h+='<ul class="m13-ed">'+w.edges.map((e,i)=>'<li data-e="'+i+'">'+w.states[e[0]]+' → '+w.states[e[1]]+': '+e[2]+'</li>').join("")+'</ul>';
  if(w.vars)h+='<div class="m13-vr">'+w.vars.map((v,i)=>'<span data-v="'+i+'"><b>'+v[0]+'</b> <i>–</i></span>').join("")+'</div>';
  h+='<p class="m13-hint">'+(w.hint||"Trạng thái và biến đọc từ RAM trong sau mỗi lệnh; ô vừa đổi được tô màu.")+'</p>';
  sec.querySelector(".m13-b").innerHTML=h;last=null;prevS=null;edge=-1;seen=null}
 function paint(m){const w=PS[pi].watch;if(!w)return;const H=sec.querySelector(".m13-h");
  if(!m){H.textContent="chưa chạy";sec.querySelectorAll(".m13-st .s").forEach(x=>x.classList.remove("on","was"));sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.remove("on"));sec.querySelectorAll(".m13-vr i").forEach(x=>x.textContent="–");last=null;prevS=null;edge=-1;return}
  if(m!==seen){seen=m;last=null;prevS=null;edge=-1}
  const vals=(w.vars||[]).map(v=>rd(m,v[1]));
  if(w.states){const s=rd(m,w.state);if(prevS!=null&&s!==prevS&&w.edges){const k=w.edges.findIndex(e=>e[0]===prevS&&e[1]===s);if(k>=0)edge=k}
   sec.querySelectorAll(".m13-st .s").forEach(x=>{x.classList.toggle("on",+x.dataset.s===s);x.classList.toggle("was",prevS!=null&&+x.dataset.s===prevS&&s!==prevS)});
   sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.toggle("on",+x.dataset.e===edge));
   H.textContent=s<w.states.length?"trạng thái "+s+" · "+w.states[s].replace(/<[^>]+>/g,""):"trạng thái "+H2(s)+"H (ngoài bảng!)";if(s!==prevS)prevS=s}
  else H.textContent="t = "+(m.cyc*12/m.fosc*1000).toLocaleString("vi-VN",{maximumFractionDigits:3})+" ms";
  sec.querySelectorAll(".m13-vr span").forEach((x,i)=>{const v=vals[i],k=w.vars[i][2]||"hex";x.querySelector("i").textContent=k==="dec"?String(v):k==="bit"?String(v):H2(v)+"H ("+v+")";x.classList.toggle("chg",!!last&&last[i]!==v)});last=vals}
 function loop(){const sc=R&&R.querySelector(".st-scroll");if(sc){const sel=R.querySelector(".s-pre"),i=sel?+sel.value:0;
   if(i!==pi){pi=i;const p=PS[i]||{};const sp=R.querySelector(".m51-sp");if(sp&&p.speed)sp.value=p.speed;shape(p.watch);sec&&(seen=null)}
   else if(sec&&sec.parentNode!==sc)shape(PS[pi].watch);
   if(PS[pi]&&PS[pi].watch){let m=null;try{m=sim49.machine()}catch(e){}paint(m)}}
  setTimeout(loop,150)}
 if(R)loop()})();

makeQuiz("quiz49","score49",[{"q": "AT89S52, thạch anh 12 MHz, Timer 0 chế độ 2. Muốn tick 250 µs thì nạp TH0 bằng bao nhiêu?", "o": ["FAH", "FF06H", "9CH", "06H"], "a": 3, "e": "Ở 12 MHz một chu kỳ máy là 1 µs; chế độ 2 đếm từ TH0 tới FFH rồi tràn, nên cần 256 − 250 = 6. FAH = 250 là số chu kỳ, không phải giá trị nạp; 9CH = 156 cho tick 100 µs; chế độ 2 chỉ có 8 bit."}, {"q": "ISR tick gồm INC TICK và RETI, tick 250 chu kỳ máy. ISR (kể cả lệnh gọi do phần cứng) chiếm bao nhiêu phần trăm thời gian CPU?", "o": ["1,2 %", "0,4 %", "2 %", "5 %"], "a": 2, "e": "Lệnh gọi do phần cứng 2 CK + INC 1 CK + RETI 2 CK = 5 CK mỗi 250 CK = 2 %. Bỏ quên 2 CK của lệnh gọi sẽ ra 1,2 %."}, {"q": "Bộ đếm tick 8 bit: START = F0H, NOW = 04H. Đã trôi bao nhiêu tick?", "o": ["20", "236", "−236", "Không xác định vì tick đã tràn"], "a": 0, "e": "(04H − F0H) mod 256 = 14H = 20. SUBB cho đúng kết quả này (bỏ qua cờ mượn). 236 là F0H − 04H, phép trừ ngược chiều."}, {"q": "Tick 250 µs; trong một tick có ba tác vụ cùng tới lượt, tổng thời gian chạy 300 µs. Điều gì xảy ra?", "o": ["Timer 0 dừng lại cho tới khi các tác vụ chạy xong", "Tick vẫn được ISR đếm, nhưng vòng lặp chính xử lý trễ và có thể lỡ hạn các tác vụ sau", "Ngắt Timer 0 bị mất vĩnh viễn và TICK không tăng nữa", "CPU tự bỏ qua tác vụ thứ ba để kịp tick"], "a": 1, "e": "Timer chạy độc lập với chương trình nên ISR vẫn tăng TICK; vòng lặp chính bị nợ tick (TICK − LAST ≥ 2). Bộ lập lịch hợp tác không tự cắt tác vụ: người viết phải giữ tổng thời gian dưới chu kỳ tick hoặc lệch pha các tác vụ."}, {"q": "Tác vụ nút cần biết nút được giữ đủ 1 giây. Trong bộ lập lịch hợp tác nên viết thế nào?", "o": ["Gọi vòng lặp trễ 1 giây trong tác vụ rồi đọc lại nút", "Đặt vòng lặp trễ 1 giây trong ISR Timer 0", "Tắt ngắt 1 giây để đọc nút cho chính xác", "Ghi START = TICK khi thấy nhấn; mỗi lần được gọi so (TICK − START) với thời gian cần, rồi trở về ngay"], "a": 3, "e": "Tác vụ không được đứng chờ: nó nhớ thời điểm bắt đầu và kiểm tra lại ở các lần gọi sau. Trễ trong tác vụ hay trong ISR đều chặn mọi việc khác; tắt ngắt làm TICK ngừng tăng."}]);

